import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "Update a draft vendor",
    { tag: "@VEN-08" },
    async ({ apiAs }) => {
      // Background: signed in as member@northwind.test
      const member = await apiAs("member");

      // Arrange: a vendor in status "draft"
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Acme Freight"),
          category: "logistics",
          contact_email: `ops-${Date.now().toString(36)}@acmefreight.example`,
        },
      });
      expect(created.status()).toBe(201);
      const vendor = await created.json();
      expect(vendor.status).toBe("draft");

      // Act: change its contact email
      const newEmail = "billing@acmefreight.example";
      const response = await member.patch(`/api/vendors/${vendor.id}`, {
        data: { contact_email: newEmail },
      });

      // Assert: response status is 200 and the change is applied
      expect(response.status()).toBe(200);
      const updated = await response.json();
      expect(updated.id).toBe(vendor.id);
      expect(updated.contact_email).toBe(newEmail);

      // Assert: an audit event "vendor.updated" is recorded
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const trail = await auditResponse.json();
      const actions = (trail.items as { action: string }[]).map((e) => e.action);
      expect(actions).toContain("vendor.updated");
    },
  );
});
